// ═══════════════════════════════════════════════════════════════════════════
// Cloudflare Worker entry.
//
// fetch     → the Next.js app, as built by `opennextjs-cloudflare build`.
// scheduled → Cloudflare cron triggers (wrangler.jsonc "triggers.crons").
//             Each trigger runs every /api/cron/* route whose schedule
//             matches, through the app itself, with the same
//             `Authorization: Bearer $CRON_SECRET` header Vercel Cron sends.
// ═══════════════════════════════════════════════════════════════════════════

// @ts-ignore — generated by `opennextjs-cloudflare build`
import { default as handler } from "../.open-next/worker.js";
import { jobsForSchedule } from "../src/config/cron-jobs";

interface Env {
  CRON_SECRET?: string;
  NEXT_PUBLIC_APP_URL?: string;
  [key: string]: unknown;
}

async function runJob(path: string, env: Env, ctx: ExecutionContext): Promise<void> {
  const base = env.NEXT_PUBLIC_APP_URL || "https://localhost";
  const headers = new Headers({ "user-agent": "cloudflare-cron" });
  if (env.CRON_SECRET) headers.set("authorization", `Bearer ${env.CRON_SECRET}`);
  const started = Date.now();
  try {
    const res: Response = await handler.fetch(new Request(new URL(path, base), { headers }), env, ctx);
    const body = (await res.text()).slice(0, 500);
    const line = `[cron] ${path} → ${res.status} in ${Date.now() - started}ms ${body}`;
    if (res.ok) console.log(line);
    else console.error(line);
  } catch (err) {
    console.error(`[cron] ${path} threw after ${Date.now() - started}ms`, err);
  }
}

export default {
  fetch: handler.fetch,

  async scheduled(controller: ScheduledController, env: Env, ctx: ExecutionContext) {
    const jobs = jobsForSchedule(controller.cron);
    if (jobs.length === 0) {
      console.warn(`[cron] no jobs for schedule "${controller.cron}"`);
      return;
    }
    await Promise.all(jobs.map((j) => runJob(j.path, env, ctx)));
  },
} satisfies ExportedHandler<Env>;
